<?php
if (!defined('ABSPATH')) exit;
if(!is_user_logged_in()){wp_safe_redirect(add_query_arg('redirect_to',rawurlencode(home_url('/account/')),home_url('/login/')));exit;}
get_header();$user=wp_get_current_user();$q=melkino_user_property_query($user->ID);$total=(int)$q->found_posts;$published=0;$pending=0;$posts=$q->posts;foreach($posts as $p){if($p->post_status==='publish')$published++;if($p->post_status==='pending')$pending++;}$logout_url=wp_nonce_url(add_query_arg('melkino_logout','1',home_url('/')),'melkino_logout');
?>
<main class="melkino-account-page"><div class="melkino-account-container"><section class="account-head"><div class="account-user"><div class="account-avatar"><?php echo esc_html(function_exists('mb_substr')?mb_substr($user->display_name?:$user->user_login,0,1):substr($user->display_name?:$user->user_login,0,1)); ?></div><div><h1>سلام، <?php echo esc_html($user->display_name?:$user->user_login); ?> 👋</h1><p>مدیریت حساب و آگهی‌های شما در ملکینو</p></div></div><div class="account-actions"><a class="primary" href="<?php echo esc_url(home_url('/submit-property/')); ?>">+ ثبت ملک جدید</a><a class="secondary" href="<?php echo esc_url($logout_url); ?>">خروج</a></div></section><?php if(isset($_GET['deleted'])): ?><div class="account-notice">ملک انتخاب‌شده به سطل زباله منتقل شد.</div><?php elseif(isset($_GET['updated'])): ?><div class="account-notice">تغییرات آگهی ذخیره شد و برای بررسی دوباره ارسال شد.</div><?php elseif(isset($_GET['edit_error'])): ?><div class="account-notice">ویرایش آگهی انجام نشد. عنوان ملک را وارد کنید.</div><?php endif; ?><div class="account-stats"><div class="account-stat"><span>کل آگهی‌های من</span><strong><?php echo esc_html($total); ?></strong></div><div class="account-stat"><span>منتشر شده</span><strong><?php echo esc_html($published); ?></strong></div><div class="account-stat"><span>در انتظار بررسی</span><strong><?php echo esc_html($pending); ?></strong></div></div><section class="account-content"><div class="account-content-head"><h2>آگهی‌های من</h2><a href="<?php echo esc_url(home_url('/submit-property/')); ?>">ثبت آگهی جدید ←</a></div><?php if($total): foreach($posts as $p): $thumb=get_the_post_thumbnail_url($p->ID,'medium');$status_class=sanitize_html_class($p->post_status);$status_label=array('publish'=>'منتشر شده','pending'=>'در انتظار بررسی','draft'=>'پیش‌نویس','private'=>'خصوصی','future'=>'زمان‌بندی شده'); ?><article class="account-property"><div class="account-property-thumb"><?php if($thumb): ?><img src="<?php echo esc_url($thumb); ?>" alt=""><?php endif; ?></div><div><h3><?php echo esc_html(get_the_title($p)); ?></h3><div class="account-property-meta"><span class="status <?php echo esc_attr($status_class); ?>"><?php echo esc_html(isset($status_label[$p->post_status])?$status_label[$p->post_status]:$p->post_status); ?></span><?php $size=melkino_property_meta($p->ID,'area_size');if($size): ?><span><?php echo esc_html($size); ?> متر</span><?php endif; ?><?php $price=melkino_property_meta($p->ID,'price');if($price): ?><span><?php echo esc_html(melkino_price($price)); ?></span><?php endif; ?></div></div><div class="account-property-actions"><a href="<?php echo esc_url(add_query_arg('property_id',$p->ID,home_url('/edit-property/'))); ?>">ویرایش</a><?php if($p->post_status==='publish'): ?><a href="<?php echo esc_url(get_permalink($p)); ?>">مشاهده</a><?php endif; ?><form method="post" onsubmit="return confirm('این آگهی به سطل زباله منتقل شود؟');"><?php wp_nonce_field('melkino_delete_property','melkino_delete_nonce'); ?><input type="hidden" name="melkino_delete_property" value="1"><input type="hidden" name="property_id" value="<?php echo esc_attr($p->ID); ?>"><button type="submit">حذف</button></form></div></article><?php endforeach; else: ?><div class="account-empty"><strong>هنوز آگهی‌ای ثبت نکرده‌اید.</strong><span>اولین ملک خود را در ملکینو ثبت کنید تا بعد از بررسی در سایت نمایش داده شود.</span><br><a href="<?php echo esc_url(home_url('/submit-property/')); ?>">ثبت اولین ملک</a></div><?php endif; ?></section></div></main>
<?php wp_reset_postdata();get_footer(); ?>
